  const moonRender=renderOneSlideEffect;renderOneSlideEffect=function(host,e,type,layer,index=0){const before=new Set(host.children),result=moonRender.apply(this,arguments);if(type==='moonlight'){const box=[...host.children].find(x=>!before.has(x)&&x.classList.contains('fx-moonlight')),disc=box?.querySelector('.moonDisc');if(box&&disc){box.classList.add('moon-'+(e.moonPhase||'full'),'moon-color-'+(e.moonColor||'natural'));const size=70+Number(e.moonSize||5)*12;disc.style.width=disc.style.height=size+'px';box.style.setProperty('--moon-halo',String(Number(e.moonHaloStrength??7)/10));const cloud=box.querySelector('.moonCloud');if(cloud)cloud.style.opacity=String(Number(e.moonClouds??4)/10)}}return result};
